-- The Triax and Wilderness weapons of printed 141-150. Twenty new rows, plus
-- the TX-42 stub filled.
--
-- One-off data script, run once per environment. NOT a migration.
--
--   node scripts/d1-apply.mjs --local apps/character-creator/db/add-triax-gear-b-weapons.sql
--
-- Numbers were read off the OCR cache and CHECKED against renders of the pages,
-- per the Phase World precedent. Printed 148 is worth a note: its folio does not
-- appear in the OCR at all, and a render of the page foot shows "148" plainly,
-- so the page numbering is sound and only the OCR missed it.
--
-- THE TX-42 IS A STUB FILL, not a new row. add-ngr-infantry-soldier-class.sql
-- and three other NGR class scripts created it cited to the O.C.C. pages; the
-- weapons chapter on printed 145 is where it is actually statted. Four
-- published classes reference the slug, so the slug is untouched and the UPDATE
-- is guarded on the STUB marker.
--
-- THE BOOK PRINTS THREE DIFFERENT PRICES FOR THE SAME PUMP AMMUNITION and this
-- script does not reconcile them: printed 141 says a pump round is 300 credits,
-- the TX-5 entry says 400, and the TX-16 entry says 200. Each weapon row
-- carries the figure ITS OWN entry prints, and the ammunition row in batch C
-- carries the 300 from the general rule. Recorded rather than averaged.
--
-- A CONVERSION SLIP RUNS THROUGH THE PISTOL PAGES: 800 feet is printed as
-- "(224 m)" where 800 feet is 244 m. The FOOT figure is what is stored, and the
-- affected rows say so in their descriptions. This is the book's own error
-- rather than an OCR digit swap - it repeats identically across entries.
--
-- A PRICE RANGE STORES ITS LOW END in cost with the range in cost_note, which
-- is why the TX-41 reads 90,000 and the TX-42 fill reads 50,000.
--
-- Sorts after add-triax-gear-a-armor.sql and after every add-ngr-*-class.sql,
-- which is what creates the TX-42 stub - checked against the directory.

INSERT OR IGNORE INTO gear (slug, name, system, category, weight_lbs, cost, cost_note, damage, is_mega_damage, range, payload, rate_of_fire, ar, sdc, mdc, description, source_book) VALUES
('tx-5-triax-pump-pistol', 'TX-5 Triax Pump Pistol', 'rifts', 'weapon', 5, 10000, '10,000 credits for the gun and 400 credits per round; fair availability', '4D6 M.D.', 1, '800 feet (244 m)', '5 rounds, loaded manually, one round per melee action. A speed loader loads all five in four seconds - one melee action - and costs 1200 credits', 'Standard, see the Modern Weapon Proficiency section', NULL, NULL, NULL, 'The pistol version of the pump rifle, firing high explosive cartridges much smaller than a conventional grenade but packing a wallop. The rounds go out at high velocity with good range, and the blast is very concentrated - about a one foot (0.3 m) area, where a hand grenade affects an area five to twenty times larger. Like all pump weapons it can also fire DU-Rounds or U-Rounds, at only 1D6 M.D. per round, but both are excellent armour piercing cartridges and the U-Rounds stop supernatural beings healing instantly. THE BOOK PRINTS THE RANGE AS "800 feet (224 m)"; 800 feet is 244 m, and the foot figure is the one stored.', 'Rifts World Book 5: Triax and the NGR p.143'),
('tx-20-short-laser-pistol', 'TX-20 "Short" Laser Pistol', 'rifts', 'weapon', 2, 12000, '12,000 credits; good availability', '2D6 M.D.', 1, '800 feet (244 m)', '20 shots', 'Standard, see the Modern Weapon Proficiency section', NULL, NULL, NULL, 'The standard issue sidearm for officers and police in the NGR armed forces. An older style weapon using a "short" E-clip, but with good firepower, lightweight and reliable. The book prints its range as "224 m" for 800 feet, the same conversion slip the TX-5 carries.', 'Rifts World Book 5: Triax and the NGR p.143'),
('tx-22-precision-laser-pistol', 'TX-22 Precision Laser Pistol', 'rifts', 'weapon', 3, 15000, '15,000 credits; good availability', '2D4 M.D.', 1, '1000 feet (305 m)', '50 shots from a forward sliding energy clip, or 20 from a short clip', 'Standard, see the Modern Weapon Proficiency section', NULL, NULL, NULL, 'Comes standard with a forward sliding energy clip but can also take a short clip fitted into the handle. A long-range weapon with fine calibrations, ideal for target shooting. Bonus: +1 to strike on an aimed shot.', 'Rifts World Book 5: Triax and the NGR p.143'),
('tx-24-ion-pulse-pistol', 'TX-24 Ion Pulse Pistol', 'rifts', 'weapon', 4, 20000, '20,000 credits; good availability', '2D4 M.D. single shot, or 4D6 M.D. for a three-shot pulse burst', 1, '500 feet (152 m)', '30 shots from a forward sliding energy clip, or 10 from a short clip', 'Standard, see the Modern Weapon Proficiency section', NULL, NULL, NULL, 'An ion pistol with a three-shot pulse setting, trading range for punch.', 'Rifts World Book 5: Triax and the NGR p.144'),
('tx-26-particle-beam-pistol', 'TX-26 Particle Beam Pistol', 'rifts', 'weapon', 5, 35000, '35,000 credits; fair availability', '5D6 M.D.', 1, '400 feet (122 m)', '15 shots from a forward sliding energy clip, or 6 from a short clip', 'Standard, see the Modern Weapon Proficiency section', NULL, NULL, NULL, 'The hardest-hitting Triax sidearm, at the price of the shortest range and the smallest payload in the pistol line.', 'Rifts World Book 5: Triax and the NGR p.144'),
('wr-10-wilderness-ion-pistol', 'WR-10 Wilderness Ion Pistol', 'rifts', 'weapon', 2, 10000, '10,000 credits; excellent availability', '2D4 M.D.', 1, '600 feet (183 m)', '20 shots', 'Standard, see the Modern Weapon Proficiency section', NULL, NULL, NULL, 'A cheap, rugged and widely available ion sidearm from the Wilderness line, meant for civilians and travellers rather than the military.', 'Rifts World Book 5: Triax and the NGR p.144'),
('tx-11-triax-sniper-laser-rifle', 'TX-11 Triax Sniper Laser Rifle', 'rifts', 'weapon', 3, 20000, 'Black market 20,000 credits; fair availability', '3D6 M.D.', 1, '1600 feet (488 m)', '10 shots from a short clip, or 20 from a forward sliding energy clip', 'Equal to the hand to hand attacks of the user; aimed shots only, no bursts', NULL, NULL, NULL, 'A sniper laser with an infrared sight. Bonus: +1 to strike, and an aimed shot is +5 to strike.', 'Rifts World Book 5: Triax and the NGR p.144'),
('tx-16-pump-rifle', 'TX-16 Pump Rifle', 'rifts', 'weapon', 21, 30000, '30,000 credits for the gun and 200 credits per round; fair availability', '4D6 M.D.', 1, '1600 feet (488 m)', '16 rounds, loaded manually one at a time. A speed loader loads eight rounds in four seconds - one melee action - and costs 2000 credits', 'Standard, see the Modern Weapon Proficiency section', NULL, NULL, NULL, 'A new concept in mega-damage assault rifles, using projectiles rather than energy blasts - effectively a glorified grenade launcher or shotgun, and popular among wilderness people. A bit heavy, but well balanced and dependable in combat. Like all pump weapons it can also fire DU-Rounds or U-Rounds at only 1D6 M.D. per round. NOTE THE SPEED LOADER ASYMMETRY: this one reloads only half the payload in a melee action where the TX-5 pistol reloads all five of its rounds. That is what the book prints.', 'Rifts World Book 5: Triax and the NGR p.144'),
('tx-30-triax-ion-pulse-rifle', 'TX-30 Triax Ion Pulse Rifle', 'rifts', 'weapon', 7, 22000, '22,000 credits; good availability', '2D6 M.D. single shot, or 6D6 M.D. for a three-shot pulse burst', 1, '1600 feet (488 m)', '40 shots from a short E-clip, or 50 from a long E-clip', 'Standard, see the Modern Weapon Proficiency section', NULL, NULL, NULL, 'The standard Triax ion pulse rifle, and the cheapest of the pulse weapons.', 'Rifts World Book 5: Triax and the NGR p.145'),
('tx-41-laser-pulse-rifle-giant', 'TX-41 Laser Pulse Rifle (Giant Size)', 'rifts', 'weapon', 20, 90000, 'Black market 90,000 to 120,000 credits; very poor availability', '3D6 M.D. single shot, or 1D6x10 M.D. for a rapid-fire pulse of three shots', 1, '4000 feet (1200 m)', '100 shots, or cabled to a robot power supply for unlimited shots - though the cable can be cut', 'Equal to the total hand to hand attacks of the user', NULL, NULL, NULL, 'The giant-size laser pulse rifle, built for power armour and robots. Very hard to come by.', 'Rifts World Book 5: Triax and the NGR p.145'),
('tx-43-light-assault-laser-rifle', 'TX-43 Light Assault Laser Rifle', 'rifts', 'weapon', 7, 26000, '26,000 credits; good availability', 'Three settings: 6D6 S.D.C., 2D6 M.D., or 4D6 M.D.', 1, '2000 feet (610 m)', '20 blasts from a short E-clip, or 30 from a forward sliding energy clip', 'Aimed, burst or wild', NULL, NULL, NULL, 'The only rifle in the Triax line with a printed S.D.C. setting alongside its mega-damage settings, which makes it the one assault weapon that can be used without destroying what it hits.', 'Rifts World Book 5: Triax and the NGR p.146'),
('tx-45-particle-beam-rifle', 'TX-45 Particle Beam Rifle', 'rifts', 'weapon', 9, 35000, '35,000 credits; poor to fair availability', '5D6+6 M.D.', 1, '1200 feet (365 m)', '20 shots from a forward sliding energy clip, or 8 from a short clip', 'Standard, see the Modern Weapon Proficiency section', NULL, NULL, NULL, 'A heavy particle beam rifle. The damage is printed as 5D6+6, a flat addition unusual in the line and reproduced as printed.', 'Rifts World Book 5: Triax and the NGR p.146'),
('tx-50-rail-gun', 'TX-50 Rail Gun', 'rifts', 'weapon', 60, 50000, 'Black market 50,000 credits; poor to fair availability', '4D6 M.D. for a burst of 20 rounds, or 1D4 M.D. for a single round', 1, '4000 feet (1200 m), or 6000 feet (1828 m) with the scope and laser targeting', 'Short clip 200 rounds (10 bursts), light drum 600 rounds (30 bursts), heavy drum 2000 rounds (100 bursts)', 'Equal to the hand to hand attacks of the user, usually three to six', NULL, NULL, NULL, 'The standard Triax rail gun. The clip weighs 10 lbs, the light drum 30 lbs and the heavy drum 100 lbs on top of the gun itself. Bonus: +1 to strike from the built-in scope.', 'Rifts World Book 5: Triax and the NGR p.146-147'),
('tx-250-rail-gun', 'TX-250 Rail Gun', 'rifts', 'weapon', 250, 75000, 'Black market 75,000 credits; poor availability', '6D6 M.D. for a full burst of 30 rounds, 3D6 M.D. for a short burst of 15, or 1D4 M.D. for a single round', 1, '6000 feet (1828 m)', 'Short clip 300 rounds (10 full or 20 half bursts), drum 3000 rounds (100 full or 200 half bursts)', 'Equal to the combined hand to hand attacks of the user, usually four to eight', NULL, NULL, NULL, 'A heavy rail gun for power armour and robots; the ammunition drum weighs as much again as the gun. Bonuses: +1 to strike, +1 to parry and +1 to dodge.', 'Rifts World Book 5: Triax and the NGR p.147'),
('tx-500-triax-borg-rail-gun', 'TX-500 Triax Borg Rail Gun', 'rifts', 'weapon', 80, 85000, 'Black market 85,000 credits; fair availability', '6D6 M.D. for a burst of 30 rounds, 3D6 M.D. for a half burst of 15, or 1D4 M.D. for a single round. DU-Rounds add 2D6 M.D. to a full burst and 1D6 M.D. to a half burst', 1, '4000 feet (1200 m)', 'Heavy drum 1170 rounds (39 bursts), belt 390 rounds (13 bursts), or a 10 lb mini-clip of 90 rounds (3 bursts)', 'Standard, see the Modern Weapon Proficiency section', NULL, NULL, NULL, 'The cyborg rail gun. The power pack weighs 50 lbs, an ammunition belt 25 lbs, a case of six belts 150 lbs and the heavy drum 80 lbs. Bonus: +1 to strike from the built-in scope. The book prints its own errata here: the weight of the mini-clip given in early printings of Rifts Sourcebook One was in error.', 'Rifts World Book 5: Triax and the NGR p.147-148'),
('wr-15-wilderness-laser-rifle', 'WR-15 Wilderness Laser Rifle', 'rifts', 'weapon', 9, 18000, '18,000 credits; excellent availability', '3D6 M.D.', 1, '1600 feet (488 m)', '40 shots per energy drum', 'Standard, see the Modern Weapon Proficiency section', NULL, NULL, NULL, 'A rugged, widely available laser rifle from the Wilderness line. The drum-shaped E-clip unbalances it: -2 to strike fired one-handed, +1 to strike braced and fired two-handed.', 'Rifts World Book 5: Triax and the NGR p.148'),
('wr-17-wilderness-double-rifle', 'WR-17 Wilderness "Double" Rifle', 'rifts', 'weapon', 12, 24000, '24,000 credits; excellent availability', 'Ion 3D6 or 4D6 M.D. on two settings; laser 2D6 M.D.; both barrels fired together 5D6 M.D.', 1, 'Ion 1600 feet (488 m); laser 1200 feet (365 m)', '20 shots from a short E-clip', 'Standard, see the Modern Weapon Proficiency section', NULL, NULL, NULL, 'A double-barrelled rifle pairing an ion barrel with a laser barrel, either fired alone or both together.', 'Rifts World Book 5: Triax and the NGR p.148'),
('wr-19-plasma-ejector', 'WR-19 Plasma Ejector (WR-20 Giant Size)', 'rifts', 'weapon', 14, 28000, '28,000 credits; fair to good availability', '5D6 M.D.', 1, '1600 feet (488 m)', '10 shots from a short E-clip', 'Standard, see the Modern Weapon Proficiency section', NULL, NULL, NULL, 'A plasma ejector in two sizes: the WR-19 for human hands at 14 lbs (6.4 kg), and the WR-20 giant version at 25 lbs (11 kg). The stats are otherwise the same and the book prints them as one entry.', 'Rifts World Book 5: Triax and the NGR p.148'),
('tx-10-mini-missile-launcher', 'TX-10 Mini-Missile Launcher', 'rifts', 'weapon', 14, 18000, 'Black market 18,000 credits for the launcher; 2000 credits for a light missile and 3500 credits for a plasma or armour-piercing missile', 'By missile type; armour piercing 1D4x10 M.D. or plasma 1D6x10 M.D. are typical, and a light missile does 5D6 M.D.', 1, 'About one mile', 'One missile per launcher; carrying cases hold 6, 12 or 24', 'One per melee round solo, or three per melee round with a two-man team', NULL, NULL, NULL, 'A shoulder-fired mini-missile launcher. A missile weighs about 2 lbs (0.9 kg). Its sighting package is 10x telescopic to two miles (3.2 km), infrared to 2000 feet (610 m), passive nightvision to 2000 feet, and laser targeting.', 'Rifts World Book 5: Triax and the NGR p.149'),
('tx-m4-mini-missile-launch-pack', 'TX-M4 Mini-Missile Launch Pack', 'rifts', 'weapon', 30, 2000, 'The launch pack itself carries no printed price; a light missile is 2000 credits and a plasma or armour-piercing missile 3500 credits. The stored cost is the light missile, the cheaper of the two loads', 'By missile type; armour piercing 1D4x10 M.D. and plasma 1D6x10 M.D. are standard issue', 1, 'About one mile', 'Four missiles', 'One at a time, or a volley of two or four', NULL, NULL, NULL, 'A back-mounted four-shot mini-missile pack, 30 lbs (13.5 kg) empty and 38 lbs loaded. THE BOOK PRINTS NO PRICE FOR THE PACK ITSELF, only for its missiles, so the stored cost is the light missile and the cost_note says so.', 'Rifts World Book 5: Triax and the NGR p.149');

UPDATE gear
   SET weight_lbs = 9, cost = 50000,
       cost_note = 'Black market 50,000 to 75,000 credits; poor availability',
       damage = '2D6 M.D. single shot, or 1D4x10 M.D. for a rapid-fire pulse of three shots',
       is_mega_damage = 1, category = 'weapon',
       range = '2000 feet (610 m)',
       payload = '40 shots from a forward sliding energy clip',
       rate_of_fire = 'Equal to the total hand to hand attacks of the user',
       description = 'The standard NGR laser pulse rifle and the sidearm of the Triax line, issued to the infantry. The smaller sibling of the giant-size TX-41. Its "T-42" designation in some O.C.C. equipment lists is the same weapon.',
       source_book = 'Rifts World Book 5: Triax and the NGR p.145'
 WHERE slug = 'tx-42-laser-pulse-rifle' AND description LIKE '%STUB%';

-- Read the result back rather than trusting the exit code.
SELECT count(*) AS got FROM gear WHERE slug LIKE 'tx-%';

-- Records this run. See db/migrations/024-data-script-runs.sql.
INSERT INTO data_script_runs (filename) VALUES ('add-triax-gear-b-weapons.sql');
